V.log=()=>`${H("Timeline","From the 2019 quota debate to the 2026–27 placement window.","Chronology")}${[...new Set(L.filter(e=>!(e.y=="OFF"&&e.c)).map(e=>e.d.slice(0,4)))].map(y=>`<h2>${y}</h2>${L.filter(e=>!(e.y=="OFF"&&e.c)&&e.d.slice(0,4)==y).map(e=>`<div class="card ec" data-id="${e.id}" style="margin:10px 0;border-left:4px solid ${GC[e.g]}"><span class="m"><span class="id">${e.id}</span>${tag(e.g)}${e.d}</span> <b>${e.t}</b><div>${e.n.slice(0,5).map(chip).join("")}</div></div>`).join("")}`).join("")}`;
V.sources=()=>{const m={};L.forEach(e=>{(m[e.s]=m[e.s]||[]).push(e)});return`${H("Sources",`${Object.keys(m).length} sources behind ${L.length} entries.`,"Provenance")}<table><tr><th>Source</th><th>Entries</th><th>Links</th></tr>${Object.entries(m).sort((a,b)=>b[1].length-a[1].length).map(([s,es])=>`<tr><td>${s}</td><td>${es.length}</td><td>${[...new Set(es.map(e=>e.u).filter(Boolean))].map(u=>`<a href="${u}" target="_blank" rel="noopener">link</a>`).join(" · ")||"None"}</td></tr>`).join("")}</table>`};
V.verify=()=>`${H("Verify","Do not trust this archive blindly. Check each key figure at its original source.","Method")}<h2>Evidence grades</h2><div class="grid"><div class="card">${tag("C")}A primary document or official system screen, such as a KMU policy or the KMU admission portal, shown in full or photographed.</div><div class="card">${tag("R")}Reported by a news outlet or relayed by officials. Check the original article.</div><div class="card">${tag("U")}An insider claim, or a figure with no primary document behind it.</div></div><h2>Key figures</h2><table><tr><th>Figure</th><th>Meaning</th><th>Where to check</th><th>Grade</th></tr>${key.map(k=>`<tr><td><b>${k[0]}</b></td><td>${k[1]}</td><td>${k[3]?`<a href="${k[3]}" target="_blank" rel="noopener">${k[2]}</a>`:k[2]}</td><td>${tag(k[4])}</td></tr>`).join("")}</table><h2>What is still missing</h2><p>KMU’s official 2026–27 table shows what changed. Still unpublished: the PMDC order withdrawing last year’s temporary seats, the record of who decided to take the reduction from open merit rather than from quota seats, and SMDAS’s 2026–27 fee notice.</p>`;
V.download=()=>`${H("Download","The full dataset, free to copy, cite and verify.","Data")}<button id="dj">Download JSON</button><button id="dc">Download CSV</button><button id="do">Official 2026–27 tables (CSV)</button><p class="mut">Fields: id, date, type, topic, source, grade, title, description, url, college, entities.</p>`;
V.about=()=>`${H("About","A public-interest record of the 2026–27 reduction of open-merit MBBS seats in Khyber Pakhtunkhwa.","About")}<p class="lead">We gather documents, news reports and claims so that students can verify, cite and question them.</p><h2>Our position</h2><p>Open-merit seats rest on marks alone. Temporary extra seats should be the first to be withdrawn, and KMU and PMDC must publish the full category-wise seat table and say who decided the distribution.</p><h2>Fairness</h2><p>We do not dispute that students from the former tribal districts and Balochistan face real disadvantage. Nothing here is directed against them. Disadvantage calls for more capacity, not fewer merit seats. KMU officials say the six colleges reverted to their original capacity rather than lost seats, and we record that view. Our reply: the official table shows the reduction came almost entirely out of open merit, while Merged Districts and HEC seats did not change.</p><h2>Method and limits</h2><p>Every entry carries a grade and a source. The 2026–27 seat figures come from KMU’s official distribution, supplied on 18 November 2026; earlier years come from KMU’s admission policies. Insider claims are graded separately, and analysis entries show their arithmetic. Nothing here alleges a crime. College markers use approximate city coordinates. Map boundaries are from Natural Earth (public domain) at province level, with the former tribal districts shown as one area. If you find an error, send a correction with a source and the entry will be amended.</p>`;
V.compare=()=>{const y4=["2020–21","2023–24","2024–25","2025–26"],y5=y4.concat(["2026–27"]);
const mat=(rows,cols)=>`<div class="card" style="overflow-x:auto"><table><tr><th>College</th>${cols.map(c=>`<th>${c}</th>`).join("")}</tr>${P.cl.map((n,i)=>{let last=null;return`<tr><td><a class="row" href="/entity?id=${n.toLowerCase()}">${n}</a></td>${rows[i].map(v=>{const c=v==null?'<td class="mut">not listed</td>':`<td style="color:${last==null||v==last?"inherit":v>last?GRN:RED}">${v}${last!=null&&v!=last?` <small>(${sg(v-last)})</small>`:""}</td>`;if(v!=null)last=v;return c}).join("")}</tr>`}).join("")}</table></div>`;
const mir=P.cl.map((n,i)=>({n,cap:P.tot[i][4]-P.tot[i][3],ch:P.om[i][4]-P.om[i][3],t3:P.tot[i][3],t4:P.tot[i][4]}));
const capG=mir.filter(m=>m.cap>0).reduce((s,m)=>s+m.cap,0),omG=mir.filter(m=>m.cap>0).reduce((s,m)=>s+m.ch,0);
return`${H("Compare","Category-wise seats, 2020–21 to 2026–27, from KMU’s own admission policies and its official 2026–27 table. Green and red show change from the previous column.","Analysis")}<h2>Province totals by category</h2><div class="card" style="overflow-x:auto"><table><tr><th>Category</th>${y5.map(y=>`<th>${y}</th>`).join("")}</tr>${P.prov.map(r=>`<tr>${r.map((c,i)=>i?`<td>${c}</td>`:`<td><b>${c}</b></td>`).join("")}</tr>`).join("")}</table><p class="mut">* The 2024–25 and 2025–26 tables do not show the Kohat institutes (KIMS, KIDS). 2026–27 totals include Kohat and SMDAS (100 MBBS seats). 2021–22 and 2022–23 college tables were not retrieved; 2022–23 had 825 open-merit MBBS seats (secondary source).</p></div>
<h2>Open-merit MBBS seats by college</h2>${mat(P.om,y5)}<p class="mut">KIMS 2025–26 (93) comes from a student chart; every other figure is from KMU’s own policies and official table. ${tag("C")}</p>
<h2>Merged Districts quota (MBBS)</h2>${mat(P.md,y5)}<p class="mut">Unchanged at every college in 2026–27. In 2024–25, Saidu, Gomal, Bannu and Nowshera each gained 5 of these seats while losing 5 open-merit seats.</p>
<h2>HEC project seats, over and above (MBBS)</h2>${mat(P.hec,y5)}<p class="mut">Unchanged at every college in 2026–27 (91 MBBS seats and 22 BDS). They sit mostly at Ayub, Bannu, GKMC and Nowshera.</p>
<h2>Total sanctioned MBBS seats</h2>${mat(P.tot,y5)}<p class="mut">KIMS 2025–26 (115) is inferred from the 1,435 MBBS total KMU reported. Without SMDAS the 2026–27 total is 1,450.</p>
<h2>Capacity change versus open-merit change, 2025–26 to 2026–27</h2><div class="card" style="overflow-x:auto"><table><tr><th>College</th><th>2025–26 total</th><th>2026–27 total</th><th>Capacity change</th><th>Open-merit change</th></tr>${mir.map(m=>`<tr><td><a class="row" href="/entity?id=${m.n.toLowerCase()}">${m.n}</a></td><td>${m.t3}</td><td>${m.t4}</td><td style="color:${m.cap<0?RED:m.cap>0?GRN:"inherit"}"><span class="bx ${m.cap<0?"":"gain"}" style="width:${Math.abs(m.cap)*3}px"></span>${m.cap?sg(m.cap):"0"}</td><td style="color:${m.ch<0?RED:GRN}"><span class="bx ${m.ch<0?"":"gain"}" style="width:${Math.abs(m.ch)*3}px"></span>${sg(m.ch)}</td></tr>`).join("")}</table>
<p>At KMC, Ayub, Bannu, Nowshera, GKMC and KIMS, KMU’s table removes ${CAP6} seats of capacity and ${CUT6} of them come out of open merit. At Saidu, Gomal and Bacha Khan, capacity rises by ${capG} and open merit by ${omG}. Merged Districts and HEC seats do not change anywhere. KGMC keeps 150 seats but loses 2 open-merit seats. ${tag("C")}</p></div>
<h2>What PMDC’s email adds</h2><div class="card"><p>PM&amp;DC’s 2 November email (a photograph) lists Saidu 100 to 150, Bacha Khan 50 to 150 and Gomal 100 to 150, matching Dawn’s report. Those “before” numbers equal the 2020–21 approved capacity, so the extra intake since then was 15, 15 and 50 seats. The email calls last year’s intake a one-time exceptional measure and tells provinces to earmark HEC and other quotas <b>inside</b> the enhanced seats. ${tag("C")}</p><p>KMU’s official table shows how that played out: the three colleges take the extra seats almost entirely as open merit, and the colleges that were cut back lose almost entirely open-merit seats. The quota seats stay where they were.</p></div>`};
V.official=()=>{const mt=(D)=>`<div class="card" style="overflow-x:auto;padding:0"><table class="mx"><tr><th>Category</th>${D.cols.map(c=>`<th>${c}</th>`).join("")}<th>Total</th></tr>${D.rows.map(r=>`<tr class="${r[0]=="Open merit"?"hlr":r[1]=="Over and above"?"hlp":""}"><td>${r[0]}</td>${r[2].map(v=>`<td>${v}</td>`).join("")}<td><b>${r[3]}</b></td></tr>`).join("")}<tr class="tot"><td>Total</td>${D.tot.map(v=>`<td>${v}</td>`).join("")}<td>${D.gt}</td></tr></table></div>`;
const dt=(D,n)=>{const cell=d=>`<td class="${d<0?"neg":d>0?"pos":"zero"}">${d?sg(d):"0"}</td>`;return`<div class="card" style="overflow-x:auto;padding:0"><table class="mx"><tr><th>Category</th>${D.cols.slice(0,n).map(c=>`<th>${c}</th>`).join("")}<th>All</th></tr>${D.rows.map((r,i)=>{const d=r[2].slice(0,n).map((v,j)=>v-D.p25[i][j]);return`<tr class="${r[0]=="Open merit"?"hlr":r[1]=="Over and above"?"hlp":""}"><td>${r[0]}</td>${d.map(cell).join("")}${cell(d.reduce((s,x)=>s+x,0))}</tr>`}).join("")}<tr class="tot"><td>Total</td>${D.tot.slice(0,n).map((v,j)=>cell(v-D.t25[j])).join("")}${cell(D.tot.slice(0,n).reduce((s,v,j)=>s+v-D.t25[j],0))}</tr></table></div>`};
return`${H("Official 2026–27 seat tables","KMU’s college-wise distribution of sanctioned seats for the 2026–27 session, supplied on 18 November 2026, with the change since KMU’s 2025–26 table. Every figure here is confirmed.","Official table")}
<div class="enote"><b>What changed.</b> Open merit is the only large category that moves. Merged Districts, HEC project, backward-area, disabled, AJK, Gilgit-Baltistan, overseas and army seats are the same as in 2025–26 at every college that appears in both tables. General and foreign self-finance seats rise a little, and Afghan national seats fall to zero.</div>
<h2 id="mbbs">MBBS: 2026–27 distribution</h2>${mt(OF.mb)}<p class="mut">Pink row: open merit. Lilac row: Merged Districts / Balochistan project seats, listed by KMU as over and above. Backward areas are combined from 18 areas. Source: ${tag("C")} KMU official seat distribution 2026–27.</p>
<h2>MBBS: change since 2025–26</h2>${dt(OF.mb,9)}<p class="mut">Red: fewer seats. Green: more seats. KIMS and SMDAS are not in KMU’s 2025–26 table, so no change is shown for them.</p>
<h2 id="bds">BDS: 2026–27 distribution</h2>${mt(OF.bd)}<p class="mut">KCD, ADC, BKDS, SCD and KIDS are the five public dental colleges.</p>
<h2>BDS: change since 2025–26</h2>${dt(OF.bd,4)}<p class="mut">KIDS is not in KMU’s 2025–26 table. The four colleges lose 80 seats of capacity and 69 open-merit seats, while Merged Districts and project seats move between colleges.</p>
<h2>Download</h2><p><a class="chip" href="/download" style="padding:7px 14px">Download these tables as CSV</a></p>`};
const ST=[{k:"cut",n:"01 · THE CUT",big:`−${CUTN}`,t:`open-merit MBBS seats are cut at ${NUM[CUT.length]} public colleges in KMU’s official 2026–27 table, while ${GAIN} are added at ${NUM[NGAIN]} others.`},
{k:"mirror",n:"02 · THE REVERSION",big:`${CUT6} of ${CAP6}`,t:`At KMC, Ayub, Bannu, Nowshera, GKMC and KIMS, the reversion removes ${CAP6} seats of capacity. ${CUT6} of them come out of open merit. KGMC keeps its 150 seats but loses 2 open-merit seats.`},
{k:"quota",n:"03 · THE QUOTAS",big:"0",t:"seats change in the Merged Districts quota (254 MBBS seats) or in HEC project seats (91) at any college. They are the same as in 2025–26, college by college."},
{k:"email",n:"04 · ONE-TIME",big:"150",t:"PMDC’s 2 November email calls last year’s intake a one-time measure and raises Saidu, Bacha Khan and Gomal to 150 seats each. The extra seats go almost entirely to open merit: +35, +44 and +35."},
{k:"fee",n:"05 · THE FEE GAP",big:"18 times",t:`81 of the “+${HEAD}” new open-merit seats are at SMDAS. Dawn reported its fee at Rs 1.8 million a year, against Rs 87,000–102,000 for an open-merit seat in year one. The official table does not state fees.`},
{k:"gap",n:"06 · WHAT IS STILL MISSING",big:"Why",t:"The table shows what changed, not why. Still unpublished: the PMDC order withdrawing the temporary seats, the record of who chose to take the reduction from open merit, and SMDAS’s 2026–27 fee notice."}];
V.story=()=>`<section class="cream"><div class="wrap shero"><div class="kick">Data story · Khyber Pakhtunkhwa</div><h1>Where did the <span>merit seats</span> go?</h1><p class="lead">KMU’s official 2026–27 table cuts ${CUTN} open-merit MBBS seats at ${NUM[CUT.length]} public colleges. The quota seats created after 2020 did not change at any college.</p><p class="by">Scroll to read. The map changes as you go.</p></div></section><section class="cream" style="border-top:0"><div class="wrap sgrid"><div class="smap"><div class="stage"><svg id="sv"></svg></div><div class="scap" id="scap"></div></div><div>${ST.map((s,i)=>`<div class="step" data-i="${i}"><div class="scard"><div class="n">${s.n}</div><div class="big">${s.big}</div><p>${s.t}</p></div></div>`).join("")}</div></div></section><div class="wrap" style="padding-top:20px;padding-bottom:70px"><h2>Go deeper</h2><div class="pkg" style="max-width:520px"><a href="/official">The official tables<span>MBBS and BDS, every category, with changes</span></a><a href="/browse">Search all ${L.length} records<span>Every claim graded and linked</span></a><a href="/compare">Compare the years<span>Category-wise seats, 2020–27</span></a><a href="/colleges">College ledger<span>Open-merit seats by college</span></a><a href="/verify">Check the numbers<span>Where each key figure comes from</span></a></div><div class="enote">All 2026–27 figures are from KMU’s official seat distribution. KMU officials say the six colleges reverted to their original capacity rather than lost seats. Our reply: the official table shows the reduction came almost entirely out of open merit, while Merged Districts and HEC seats did not change.</div></div>`;
